def main():
    parts = sys.stdin.read().split()
    if len(parts) >= 3:
        nums = sorted([int(parts[0]), int(parts[1]), int(parts[2])])
        print(f"{nums[0]} {nums[1]} {nums[2]}")

if __name__ == '__main__':
    main()

